<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\ChartOfAccount;use App\Models\Currency;use Illuminate\Http\Request;class ChartOfAccountController extends Controller{public function index(Request $r){return ['data'=>ChartOfAccount::where('project_id',$r->user()->project_id)->latest()->get()];}public function options(){return ['data'=>['currencies'=>Currency::where('status_active',1)->get(['id','currency_code','currency_name'])]];}public function store(Request $r){$d=$this->valid($r)+['project_id'=>$r->user()->project_id,'created_by'=>$r->user()->id];return response()->json(['data'=>ChartOfAccount::create($d)],201);}public function show(Request $r,ChartOfAccount $chartOfAccount){$this->guard($r,$chartOfAccount);return ['data'=>$chartOfAccount];}public function update(Request $r,ChartOfAccount $chartOfAccount){$this->guard($r,$chartOfAccount);$chartOfAccount->update($this->valid($r)+['updated_by'=>$r->user()->id]);return ['data'=>$chartOfAccount->fresh()];}public function destroy(Request $r,ChartOfAccount $chartOfAccount){$this->guard($r,$chartOfAccount);$chartOfAccount->delete();return ['success'=>true];}private function guard(Request $r,ChartOfAccount $a):void{abort_unless((int)$a->project_id===(int)$r->user()->project_id,404);}private function valid(Request $r):array{return $r->validate(['account_number'=>'required|max:30','account_name'=>'required','account_sub_type'=>'required','opening_balance'=>'nullable|numeric','opening_balance_date'=>'nullable|date','currency_id'=>'nullable|exists:currencies,id','status_active'=>'required|boolean','notes'=>'nullable','description'=>'nullable','dedicated_account_holders'=>'nullable|array']);}}
